/* words.js - the English wordlist behind the anagram, spelling and word-game skills.
 *
 * 65,381 words, filtered from the SCOWL-derived
 * american-english and british-english lists shipped with Debian (both spellings
 * are included, so "colour" and "color" are each valid). Proper nouns,
 * possessives and anything with punctuation are excluded - which is why
 * spellCheck reports a capitalised unknown word as "not in the list" rather
 * than as a misspelling.
 *
 * No length limit. An earlier cut kept only two-to-nine-letter words to save
 * 90 KB, and spellCheck then flagged "definitely" as an error because the word
 * is ten letters long. A spell checker missing the long words is worse than no
 * spell checker, so the whole list stays.
 *
 * Stored front-coded: the list is sorted, so each entry records how many leading
 * characters it shares with the one before it - a lowercase letter, a=0 to z=25 -
 * followed by the rest of the word. That more than halves it, from 596 KB to 273 KB, for
 * about six lines of decoding. The table decodes once, on first use, so a
 * session that never plays a word game never pays for it.
 */

