let words = null;
let anagramIndex = null;

export function allWords () {
  if (words) return words;
  words = [];
  let prev = '';
  for (const line of ENCODED.trim().split('\n')) {
    const shared = line.charCodeAt(0) - 97;
    const word = prev.slice(0, shared) + line.slice(1);
    words.push(word);
    prev = word;
  }
  return words;
}

const lookup = () => (anagramIndex ??= (() => {
  /* Anagrams share one key: their letters in sorted order. Building the index
     once turns every later anagram question into a single map read instead of a
     scan of 45,000 words. */
  const map = new Map();
  for (const w of allWords()) {
    const key = [...w].sort().join('');
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(w);
  }
  return map;
})());

export const anagramKey = (s) => [...String(s).toLowerCase().replace(/[^a-z]/g, '')].sort().join('');
export const anagramsOf = (letters) => (lookup().get(anagramKey(letters)) ?? []);

let wordSet = null;
export const isWord = (w) => (wordSet ??= new Set(allWords())).has(String(w).toLowerCase());

/* Every word that can be spelled from a multiset of letters. Counts, not a
   regex: "letter" needs two Ts and a bag holding one T must not match it. */
export function spellableFrom (letters, minLength = 3) {
  const have = new Map();
  for (const c of String(letters).toLowerCase().replace(/[^a-z]/g, '')) have.set(c, (have.get(c) ?? 0) + 1);
  const out = [];
  for (const w of allWords()) {
    if (w.length < minLength || w.length > [...have.values()].reduce((a, b) => a + b, 0)) continue;
    const need = new Map();
    let ok = true;
    for (const c of w) {
      const n = (need.get(c) ?? 0) + 1;
      if (n > (have.get(c) ?? 0)) { ok = false; break; }
      need.set(c, n);
    }
    if (ok) out.push(w);
  }
  return out;
}
